/* Initial/default callout styling */

div.callout {
    --callout-color: var(--mw);
	--callout-icon: lucide-moon;
	border-radius: 3px;
	border-style: dashed;
	border-width: 2px;
	border-color: color-mix(in srgb, var(--callout-color), transparent 65%);
	background-image: var(--moon-icon-faint);
	background-size: var(--callout-bg-stamp-size);
	background-position: var(--callout-bg-stamp-position);
	background-repeat: no-repeat;
	box-shadow: inset 0px 0px 2px 4px color-mix(in srgb, var(--callout-color), transparent 91%);
}


/* Callout properties - applied before others */
body .callout[data-callout*="readout"]  {
    --callout-icon: lucide-binary;
    --callout-color: var(--color-green);
	color: color-mix(in srgb,var(--callout-color), var(--callout-lum) 30%);
	border-style: solid;
	border-radius: 0px;
	border-width: 2px;
	background: 
        repeating-linear-gradient(
            0deg, var(--scan-color1), var(--scan-color1) var(--scan-spacing), 
            var(--scan-color2) var(--scan-spacing), 
            var(--scan-color2) var(--scan-spacing-and-width)
        );
	-webkit-mask-image: 
        repeating-linear-gradient(
            0deg, var(--mask-color1), var(--mask-color1) var(--mask-spacing), 
            var(--mask-color2) var(--mask-spacing), 
            var(--mask-color2) var(--mask-spacing-and-width)
        );
}
.callout[data-callout="readout"] .callout-icon::after {
	content: "://";
	padding-left: 5px;
}

