/* Mask animations */

.whim-anim-mask-hypno {
    animation: mask-hypno 240s ease infinite;
}
@keyframes mask-hypno {
    0% {
        mask-size: 1% 50%;
    }
    50% {
        mask-size: 200% 1%;
    }
    100% {
        mask-size: 1% 50%;
    }
}

.whim-anim-mask-zoom {
    animation: mask-zoom 240s ease infinite;
}
@keyframes mask-zoom {
    0% {
        mask-size: 1% 1%;
    }
    50% {
        mask-size: 200% 200%;
    }
    100% {
        mask-size: 1% 1%;
    }
}

.whim-anim-mask-shift {
    animation: mask-shift 180s ease infinite;
}
@keyframes mask-shift {
    0% {
        mask-position: 50% 50%;
    }
    50% {
        mask-position: 150% 150%;
    }
    100% {
        mask-position: 50% 50%;
    }
}



/* BG Animations */

.whim-anim-basicgradient {
    animation: gradient 60s ease infinite;
}
@keyframes gradient {
    0% {
        background-position: 0% 50%;
    }
    50% {
        background-position: 100% 50%;
    }
    100% {
        background-position: 0% 50%;
    }
}
body.whim-anim-slowgradient .workspace,
.whim-anim-slowgradient {
    animation: gradient 240s ease infinite;
}
@keyframes gradient {
    0% {
        background-position: 0% 50%;
    }
    50% {
        background-position: 100% 50%;
    }
    100% {
        background-position: 0% 50%;
    }
}
.whim-anim-hypno {
    animation: hypno 240s ease infinite;
}
@keyframes hypno {
    0% {
        background-position: 0% 50%;
		background-size: 100% 100%;
    }
    25% {
		background-size: 200% 1%;
    }
    50% {
        background-position: 50% 0%;
		background-size: 1% 1%;
    }
    75% {
		background-size: 10% 200%;
    }
    100% {
        background-position: 0% 50%;
		background-size: 100% 100%;
    }
}
.whim-anim-playagate {
    animation: play 360s ease infinite;
}
@keyframes play {
    0% {
        background-position: 1% 100%;
		background-size: 1% 100%;
    }
    25% {
        background-position: 50% 50%;
		background-size: 50% 50%;
    }
    50% {
        background-position: 100% 1%;
		background-size: 100% 1%;
    }
    75% {
        background-position: 50% 50%;
		background-size: 50% 50%;
    }
    100% {
        background-position: 1% 100%;
		background-size: 1% 100%;
    }
}
.whim-anim-slow {
    animation: slow 360s ease infinite;
}
@keyframes slow {
    0% {
        background-position: 1% 100%;
		background-size: 100% 100%;
    }
    25% {
        background-position: 50% 50%;
		background-size: 100% 50%;
    }
    50% {
        background-position: 100% 1%;
		background-size: 200% 25%;
    }
    75% {
        background-position: 50% 50%;
		background-size: 100% 50%;
    }
    100% {
        background-position: 1% 100%;
		background-size: 100% 100%;
    }
}
.whim-anim-drift {
    animation: drift var(--nbg-anim-speed) ease infinite;
}
@keyframes drift {
	0% {
		background-position: 20% 20%;
	}
	50% {
		background-position: 200% 200%;
	}
	100% {
		background-position: 20% 20%;
	}
}
body.whim-anim-zoom .workspace,
.whim-anim-zoom {
    animation: zoom 360s ease infinite;
}
@keyframes zoom {
	0% {
		background-size: 20% 20%;
	}
	50% {
		background-size: 200% 200%;
	}
	100% {
		background-size: 20% 20%;
	}
}
.whim-anim-rotisserie {
    animation: spin 360s ease infinite;
}
@keyframes spin {
	0% {
		transform: rotate(0turn);
	}
	100% {
		transform: rotate(1turn);
	}
}

